('newsmaker_cache_ebook_api_ebooks_slug_perdagangan-berjangka-dan-komoditi', 'a:7:{i:0;a:9:{s:2:\"id\";i:125;s:5:\"title\";s:22:\"Legalitas dan Keamanan\";s:4:\"slug\";s:33:\"legalitas-dan-keamanan-1753951684\";s:9:\"deskripsi\";s:516:\"eBook \"Legalitas dan Keamanan\" membahas pentingnya pemahaman aspek hukum dan keamanan di era digital, di mana informasi dan teknologi berkembang pesat. Melalui buku ini, pembaca diajak mengenal dasar-dasar legalitas, perlindungan data, serta risiko keamanan yang sering diabaikan baik dalam kehidupan pribadi maupun bisnis. Dengan bahasa yang sederhana dan contoh kasus yang relevan, eBook ini memberikan panduan praktis untuk membangun kesadaran hukum dan menjaga keamanan informasi di tengah tantangan dunia modern\";s:5:\"cover\";s:68:\"uploads/cover/1753428927_E-Book Legalitas dan Keamanan_page-0001.jpg\";s:4:\"file\";s:58:\"uploads/ebook/1753428927_E-Book Legalitas dan Keamanan.pdf\";s:9:\"folder_id\";i:1;s:10:\"created_at\";s:27:\"2025-07-10T06:06:55.000000Z\";s:10:\"updated_at\";s:27:\"2025-07-31T08:48:04.000000Z\";}i:1;a:9:{s:2:\"id\";i:126;s:5:\"title\";s:14:\"Pengenalan PBK\";s:4:\"slug\";s:25:\"pengenalan-pbk-1755077655\";s:9:\"deskripsi\";s:591:\"Perdagangan Berjangka Komoditi (PBK) adalah suatu kegiatan jual beli kontrak berjangka atas komoditas tertentu, seperti emas, minyak, atau mata uang, yang diperdagangkan di bursa berjangka. PBK memungkinkan para pelaku pasar untuk melakukan lindung nilai (hedging) terhadap fluktuasi harga, sekaligus memberikan peluang investasi dengan potensi keuntungan maupun risiko yang tinggi. Sebagai instrumen keuangan yang diatur oleh Badan Pengawas Perdagangan Berjangka Komoditi (Bappebti), PBK dijalankan dalam kerangka hukum yang ketat untuk menjaga keamanan, transparansi, dan integritas pasar.\";s:5:\"cover\";s:64:\"uploads/cover/1753428953_E-Book Pengenalan PBK (2)_page-0001.jpg\";s:4:\"file\";s:54:\"uploads/ebook/1753428953_E-Book Pengenalan PBK (2).pdf\";s:9:\"folder_id\";i:1;s:10:\"created_at\";s:27:\"2025-07-10T07:35:19.000000Z\";s:10:\"updated_at\";s:27:\"2025-08-13T09:34:15.000000Z\";}i:2;a:9:{s:2:\"id\";i:127;s:5:\"title\";s:37:\"Sejarah dan Regulasi PBK di Indonesia\";s:4:\"slug\";s:48:\"sejarah-dan-regulasi-pbk-di-indonesia-1755077730\";s:9:\"deskripsi\";s:125:\"Sejarah Singkat PBK di Indonesia\r\nUndang-Undang dan Peraturan Terkait\r\nPeran Bappebti\r\nBursa dan Lembaga Kliring di Indonesia\";s:5:\"cover\";s:37:\"uploads/cover/1753934386_COVER EB.jpg\";s:4:\"file\";s:37:\"uploads/ebook/1753934386_E-Book 3.pdf\";s:9:\"folder_id\";i:1;s:10:\"created_at\";s:27:\"2025-07-31T03:59:46.000000Z\";s:10:\"updated_at\";s:27:\"2025-08-13T09:35:30.000000Z\";}i:3;a:9:{s:2:\"id\";i:128;s:5:\"title\";s:55:\"Cara Kerja Kontrak Berjangka: Margin, Leverage, dan Lot\";s:4:\"slug\";s:52:\"cara-kerja-kontrak-berjangka-margin-leverage-dan-lot\";s:9:\"deskripsi\";s:55:\"Cara Kerja Kontrak Berjangka: Margin, Leverage, dan Lot\";s:5:\"cover\";s:37:\"uploads/cover/1753946613_COVER EB.jpg\";s:4:\"file\";s:39:\"uploads/ebook/1753946613_E-Book NM4.pdf\";s:9:\"folder_id\";i:1;s:10:\"created_at\";s:27:\"2025-07-31T07:23:33.000000Z\";s:10:\"updated_at\";s:27:\"2025-07-31T07:23:33.000000Z\";}i:4;a:9:{s:2:\"id\";i:129;s:5:\"title\";s:40:\"Perbedaan Futures dengan Saham dan Forex\";s:4:\"slug\";s:40:\"perbedaan-futures-dengan-saham-dan-forex\";s:9:\"deskripsi\";s:97:\"Perbedaan Futures dengan Saham dan Forex\r\nJam transaksi mekanisme \r\nTujuan perdagangan dan Resiko\";s:5:\"cover\";s:37:\"uploads/cover/1753950072_COVER EB.jpg\";s:4:\"file\";s:37:\"uploads/ebook/1753950072_E-Book 5.pdf\";s:9:\"folder_id\";i:1;s:10:\"created_at\";s:27:\"2025-07-31T08:21:12.000000Z\";s:10:\"updated_at\";s:27:\"2025-07-31T08:21:12.000000Z\";}i:5;a:9:{s:2:\"id\";i:130;s:5:\"title\";s:28:\"Komoditi yang Diperdagangkan\";s:4:\"slug\";s:28:\"komoditi-yang-diperdagangkan\";s:9:\"deskripsi\";s:89:\"Jenis ragam komoditiyang diperdagangkan di indonesia dan cukup diminati oleh palaku pasar\";s:5:\"cover\"