(890, NULL, 'Legalitas dan Keamanan', 'legalitas-dan-keamanan', NULL, 'eBook \"Legalitas dan Keamanan\" membahas pentingnya pemahaman aspek hukum dan keamanan di era digital, di mana informasi dan teknologi berkembang pesat. Melalui buku ini, pembaca diajak mengenal dasar-dasar legalitas, perlindungan data, serta risiko keamanan yang sering diabaikan baik dalam kehidupan pribadi maupun bisnis. Dengan bahasa yang sederhana dan contoh kasus yang relevan, eBook ini memberikan panduan praktis untuk membangun kesadaran hukum dan menjaga keamanan informasi di tengah tantangan dunia modern', 'uploads/cover/1753428927_E-Book Legalitas dan Keamanan_page-0001.jpg', 'uploads/ebook/1753428927_E-Book Legalitas dan Keamanan.pdf', 8, '2025-09-26 15:25:42', '2025-09-26 15:25:42', NULL),
(891, NULL, 'Pengenalan PBK', 'pengenalan-pbk', NULL, 'Perdagangan Berjangka Komoditi (PBK) adalah suatu kegiatan jual beli kontrak berjangka atas komoditas tertentu, seperti emas, minyak, atau mata uang, yang diperdagangkan di bursa berjangka. PBK memungkinkan para pelaku pasar untuk melakukan lindung nilai (hedging) terhadap fluktuasi harga, sekaligus memberikan peluang investasi dengan potensi keuntungan maupun risiko yang tinggi. Sebagai instrumen keuangan yang diatur oleh Badan Pengawas Perdagangan Berjangka Komoditi (Bappebti), PBK dijalankan dalam kerangka hukum yang ketat untuk menjaga keamanan, transparansi, dan integritas pasar.', 'uploads/cover/1753428953_E-Book Pengenalan PBK (2)_page-0001.jpg', 'uploads/ebook/1753428953_E-Book Pengenalan PBK (2).pdf', 8, '2025-09-26 15:25:42', '2025-09-26 15:25:42', NULL),
(892, NULL, 'Sejarah dan Regulasi PBK di Indonesia', 'sejarah-dan-regulasi-pbk-di-indonesia', NULL, 'Sejarah Singkat PBK di Indonesia\r\nUndang-Undang dan Peraturan Terkait\r\nPeran Bappebti\r\nBursa dan Lembaga Kliring di Indonesia', 'uploads/cover/1753934386_COVER EB.jpg', 'uploads/ebook/1753934386_E-Book 3.pdf', 8, '2025-09-26 15:25:42', '2025-09-26 15:25:42', NULL),
