INSERT INTO `post_tests` (`id`, `session_id`, `question`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `created_at`, `updated_at`) VALUES
(102, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Berikut ini merupakan bagian dari Analisa Teknikal, </span><b>kecuali</b><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">...</span></p>', 'Analisis laporan keuangan perusahaan', 'Pola candlestick', 'Indikator teknikal seperti Moving Average', 'Support dan Resistance', 'A', '2025-09-16 04:50:06', '2025-09-16 04:50:06'),
(103, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> </span><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Untuk mengetahui arah pergerakan harga, analisis teknikal sering menggunakan wahana grafik sebagai medianya. Jenis grafik yang umum digunakan adalah...</span></p>', 'Line, Bollingerband, Candlestick, dan Bar', 'Point and Figure, Candlestick, Line dan Bar chart', 'Candlestick, Moving Average, Volume, dan Line', 'Semua jawaban benar', 'B', '2025-09-16 04:50:36', '2025-09-16 04:50:36'),
(104, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Apa yang dimaksud dengan \"</span><b>support</b><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">\" dalam analisis teknikal ? </span></p>', 'Tingkat harga di mana harga cenderung mengalami penurunan tajam', 'Tingkat harga di mana permintaan cukup kuat untuk mencegah harga turun lebih jauh', 'Tingkat harga di mana penawaran cukup kuat untuk mencegah harga naik lebih jauh', 'Garis yang digunakan untuk menghubungkan titik tertinggi dalam grafik harga', 'B', '2025-09-16 04:51:07', '2025-09-16 04:51:07'),
(105, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Menurut Teori Dow, terdapat tiga jenis tren pasar utama. Manakah dari pernyataan berikut yang </span><strong>tidak</strong><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> termasuk dalam tren pasar menurut Teori Dow?</span></p>', 'Tren Primer (Primary Trend)', 'Tren Sekunder (Secondary Trend)', 'Trend Musiman (Seasonal Trend)', 'Trend Minor (Minor Trend)', 'C', '2025-09-16 04:51:37', '2025-09-16 04:51:37'),
(106, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Berikut adalah komponen data yang ada di dalam Candlestick.</span></p>', 'Open, High, Low dan Time', 'Open, Support, Resistance dan Close', 'Open, Close, Range, dan Volume', 'Open, High, Low, Close', 'D', '2025-09-16 04:52:31', '2025-09-16 04:52:31'),
(107, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Yang dimaksud dengan </span><strong>reversal</strong><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> dalam pergerakan harga adalah </span></p>', 'Pergerakan harga yang terus berlanjut dalam arah tren yang sama', 'Perubahan sementara dalam tren utama yang kemudian kembali melanjutkan arah semula', 'Kenaikan volume perdagangan tanpa perubahan signifikan pada arah harga', 'Pembalikan arah tren utama, dari tren naik ke tren turun atau sebaliknya', 'D', '2025-09-16 04:53:06', '2025-09-16 04:53:06'),
(108, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Dibawah ini salah satu Intrumen yang dapat  dapat digunakan untuk menentukan Support atau Resistance ?</span></p>', 'Candlestick', 'Volume', 'Trendline', 'Moving Average', 'B', '2025-09-16 04:53:39', '2025-09-16 04:53:39'),
(109, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> Resistance dalam analisis teknikal adalah semua hal berikut ini, </span><b>kecuali</b><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">:</span></p>', 'Batas bawah yang mencegah harga turun lebih jauh dan cenderung terjadi pembelian', 'Area di mana investor cenderung menjual, menganggapnya sebagai harga yang sudah cukup tinggi', 'Level harga di mana harga cenderung memantul kembali setelah mengalami kenaikan', 'Tingkat harga di mana penawaran cukup kuat untuk menghentikan kenaikan harga lebih lanjut', 'A', '2025-09-16 04:54:07', '2025-09-16 04:54:07'),
(110, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Umumnya Gap Up dalam analisis teknikal terjadi karena:  </span></p>', 'Harga saham mencapai level support yang kuat', 'Volume perdagangan sangat rendah pada sesi sebelumnya', 'Adanya berita positif atau sentimen pasar yang baik terhadap saham tersebut', 'Kenaikan signifikan dalam harga penutupan dibandingkan hari sebelumnya', 'D', '2025-09-16 04:54:32', '2025-09-16 04:54:32'),
(111, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Fungsi dari Moving Average dalam analisis teknikal adalah:</span></p>', 'Menghaluskan fluktuasi harga untuk mengidentifikasi tren jangka panjang', 'Menunjukkan harga tertinggi dan terendah dari suatu aset dalam periode tertentu', 'Mengukur volatilitas pasar dengan menghitung deviasi standar dari harga', 'Menunjukkan kondisi overbought dan oversold suatu aset', 'A', '2025-09-16 04:55:03', '2025-09-16 04:55:03'),
(114, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> Dibawah ini adalah jenis moving average yang lazim digunakan seorang analis teknikal, kecuali:</span></p>', 'Exponential Moving Average (EMA)', 'Simple Moving Average (SMA)', 'Random Moving Average (RMA)', 'Weighted Moving Average (WMA)', 'C', '2025-09-16 04:55:46', '2025-09-16 04:55:46'),
(115, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Gap Down umumnya disebabkan oleh ?</span></p>', 'Rilis berita positif yang meningkatkan minat beli', 'Penurunan tajam pada harga dari penutupan sebelumnya', 'Peristiwa yang memicu peningkatan permintaan pasar', 'Adanya pembelian besar dari institusi yang mendorong harga naik', 'B', '2025-09-16 04:56:12', '2025-09-16 04:56:12'),
(116, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Apa yang ditunjukkan oleh pola \"Double Top\"?</span></p>', 'Pembalikan tren naik ke tren turun', 'Tren turun yang berlanjut', 'Kondisi pasar yang overbought', 'Penurunan volume perdagangan', 'A', '2025-09-16 04:56:37', '2025-09-16 04:56:37'),
(120, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> Apa yang dimaksud dengan \"overbought\" dalam konteks analisis teknikal ?</span></p>', 'Ketika harga saham sudah terlalu tinggi dan kemungkinan akan turun', 'Ketika harga saham sudah terlalu rendah dan kemungkinan akan naik', 'Ketika ada terlalu banyak pembeli dibandingkan penjual', 'Ketika volume perdagangan sangat rendah', 'A', '2025-09-16 04:57:41', '2025-09-16 04:57:41'),
(121, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Dalam analisis teknikal, </span><strong>level psikologis</strong><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> adalah level harga yang sering diperhatikan oleh para trader dan investor karena cenderung memicu pergerakan harga signifikan. Level psikologis biasanya terjadi pada angka-angka bulat, misalnya 100, 1.000, atau 10.000. Mengapa level psikologis ini penting dalam perdagangan saham?  </span></p>', 'Karena level ini menunjukkan perhitungan teknis yang akurat dari indikator momentum.', 'Karena banyak trader dan investor cenderung menempatkan order jual atau beli di level harga bulat, yang sering kali menyebabkan peningkatan volume transaksi.', 'Karena level psikologis merupakan titik support dan resistance yang ditentukan oleh algoritma perdagangan otomatis.', 'Karena level psikologis dipengaruhi oleh perhitungan Fibonacci Retracement yang akurat.', 'B', '2025-09-16 04:58:05', '2025-09-16 04:58:05'),
(123, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Pada grafik candlestick, formasi </span><strong>\"Doji\"</strong><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> biasanya menandakan apa?</span></p>', 'Tren yang kuat akan berlanjut.', 'Pasar dalam kondisi overbought.', 'Harga akan bergerak dengan sangat volatil dalam waktu dekat.', 'Ada keraguan antara pembeli dan penjual sehingga mungkin terjadi pembalikan tren.', 'D', '2025-09-16 04:58:36', '2025-09-16 04:58:36'),
(124, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Formasi </span><strong>\"Bullish Engulfing\"</strong><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> pada candlestick biasanya diartikan sebagai:</span></p>', 'Sinyal pembalikan dari tren turun menjadi tren naik.', 'Sinyal kelanjutan dari tren turun.', 'Sinyal bahwa tren naik akan segera berakhir.', 'Sinyal keraguan di pasar dan kemungkinan tren sideways.', 'A', '2025-09-16 04:59:00', '2025-09-16 04:59:00'),
(126, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Ketika Anda melihat pola </span><strong>\"Evening Star\"</strong><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\"> pada grafik candlestick, pola ini umumnya menandakan:</span></p>', 'Potensi kelanjutan tren naik.', 'Kondisi pasar yang stabil tanpa arah yang jelas.', 'Potensi pembalikan dari tren naik menjadi tren turun.', 'Pasar dalam kondisi overbought.', 'B', '2025-09-16 05:00:18', '2025-09-16 05:00:18'),
(127, 46, '<p><span style=\"color:rgb(32,33,36);font-family:\'docs-Roboto\';font-size:16px;background-color:rgb(241,243,244);\">Dalam analisis teknikal, \"bullish breakout\" terjadi ketika: </span></p>', 'Harga turun di bawah level support', 'Harga naik di atas level resistance', 'Harga tidak bergerak dalam waktu yang lama', 'Pola candlestick menunjukkan tren naik', 'B', '2025-09-23 03:54:15', '2025-09-23 03:54:15'),
(128, 46, '<p><span style=\"font-weight:bolder;font-family:Figtree, \'ui-sans-serif\', \'system-ui\', sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\';\">Candlestick Hammer</span><span style=\"font-size:16px;color:rgb(32,33,36);font-family:\'docs-Roboto\';background-color:rgb(241,243,244);\"> biasanya muncul pada saat:</span></p>', 'Awal tren naik.', 'Akhir tren naik, mengindikasikan potensi penurunan harga.', 'Akhir tren turun, mengindikasikan potensi pembalikan ke atas.', 'Saat pasar sedang dalam fase konsolidasi.', 'C', '2025-09-23 03:56:27', '2025-09-23 03:56:27'),
